#[derive(Clone, PartialEq, Eq, Debug)]
pub enum Pattern {
    Plain(String),
    EscapeSequences(String), // Kate mode: \n \t \xNN \uNNNN in the pattern are expanded before a plain search
    Regex(String),
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct SearchQuery {
    pub pattern: Pattern,
    pub case_sensitive: bool,
    pub whole_words: bool,       // word boundary on both sides; ignored for Regex (use \b)
    pub range: Option<CharRange>, // None = whole buffer
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Match { pub range: CharRange, pub captures: Vec<Option<CharRange>> } // captures[0] == whole match for Regex; empty otherwise

pub fn find_all(buf: &TextBuffer, q: &SearchQuery) -> Result<Vec<Match>, SearchError>;
/// Wraps around the range when `wrap` is true; never returns the empty match at `from` twice.
pub fn find_next(buf: &TextBuffer, q: &SearchQuery, from: Offset, backwards: bool, wrap: bool) -> Result<Option<Match>, SearchError>;
/// One Transaction for all matches. `replacement` supports $0..$9, ${name}, \0..\9 and \n \t escapes.
pub fn replace_all(buf: &TextBuffer, q: &SearchQuery, replacement: &str) -> Result<(Transaction, usize), SearchError>;
pub fn expand_replacement(replacement: &str, m: &Match, buf: &TextBuffer) -> String;

#[derive(Debug, PartialEq, Eq)]
pub enum SearchError { InvalidRegex(String), InvalidEscape { at: usize } }
